lca = self.lca(root, p, q)
queue = deque([lca])
cur_dep, p_dep, q_dep = 0, 0, 0
while queue:
    n = len(queue)
    for _ in range(n):
        node = queue.popleft()
        if node:
            if node.val == p:
                p_dep = cur_dep
            if node.val == q:
                q_dep = cur_dep
            queue.append(node.left)
            queue.append(node.right)
    cur_dep += 1
return p_dep + q_dep
